"""The book file: a SQLite database with numbered schema versions (``PRAGMA user_version``)."""

import contextlib
import dataclasses
import datetime
import json
import os
import re
import sqlite3
from dataclasses import dataclass, field
from typing import Any, List

from tallybook.accounts import Chart, ChartError, valid_path
from tallybook.budgets import Budget
from tallybook.csvimport import ImportProfile, import_csv as _import_csv, parse_profile
from tallybook.currency import RateTable, CurrencyError, currency as _currency
from tallybook.errors import (ConflictError, NotFoundError, TallybookError,
                              ValidationError)
from tallybook.journal import Journal
from tallybook.ledger import Ledger, LedgerError
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, format_minor
from tallybook.query import Query, parse_query
from tallybook.recurring import Recurring, instantiate, occurrences
from tallybook.rules import parse_rules

LATEST_VERSION = 4

_BUSY_TIMEOUT = 5.0
_TYPES = ("asset", "liability", "equity", "income", "expense")
_PROFILE_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NAME_CHARS = re.compile(r"[A-Za-z0-9_-]+")
_MAX_INT = 2 ** 63 - 1


@dataclass
class BulkAdd:
    """Result of :meth:`Store.add_transactions`."""

    added: List[Transaction] = field(default_factory=list)
    skipped: List[int] = field(default_factory=list)


@dataclass
class ImportOutcome:
    """Result of :meth:`Store.import_csv`."""

    added: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: List[Any] = field(default_factory=list)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _iso(value):
    return None if value is None else value.isoformat()


def _stored_date(text):
    try:
        return datetime.date.fromisoformat(text)
    except (TypeError, ValueError):
        raise ConflictError("the book holds an invalid date: %r" % (text,))


def _optional_date(text):
    return None if text is None else _stored_date(text)


def _path_key(path):
    return path.split(":")


def _check_text(value, what):
    if not isinstance(value, str):
        raise ValidationError("%s must be text, not %r" % (what, value))
    return value


def _check_limit(value, what, allow_none):
    if value is None and allow_none:
        return None
    if not _is_int(value) or value < 0:
        raise ValidationError("%s must be a whole number of at least 0, not %r" % (what, value))
    return min(value, _MAX_INT)


def _migration_error(step, exc):
    return ConflictError("migration to version %d failed: %s" % (step, exc))


class Store:
    """One book file. Use :meth:`Store.open`; a store is a context manager."""

    def __init__(self, path, conn, version):
        self.path = path
        self._conn = conn
        self._version = version

    # ------------------------------------------------------------------ opening

    @classmethod
    def open(cls, path, create=False):
        if isinstance(path, bytes):
            path = os.fsdecode(path)
        elif not isinstance(path, str):
            try:
                path = os.fspath(path)
            except TypeError:
                raise ValidationError("path must be text or a path object, not %r" % (path,))
        if os.path.isdir(path):
            raise ConflictError("%s is a directory, not a tallybook book" % path)
        exists = os.path.exists(path)
        if not exists:
            if not create:
                raise NotFoundError("no such database: %s" % path)
            parent = os.path.dirname(os.path.abspath(path))
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % parent)
        try:
            conn = sqlite3.connect(os.path.abspath(path), timeout=_BUSY_TIMEOUT,
                                   isolation_level=None, check_same_thread=False)
        except sqlite3.Error as exc:
            raise ConflictError("cannot open %s: %s" % (path, exc))
        try:
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            tables = conn.execute("SELECT COUNT(*) FROM sqlite_master").fetchone()[0]
            conn.execute("PRAGMA foreign_keys = ON")
        except sqlite3.Error as exc:
            conn.close()
            raise ConflictError("%s is not a tallybook book: %s" % (path, exc))
        if version == 0 and tables:
            conn.close()
            raise ConflictError("%s is not a tallybook book (no schema version)" % path)
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError("%s is at version %d, newer than this tallybook (version %d)"
                                % (path, version, LATEST_VERSION))
        store = cls(path, conn, version)
        if create and version == 0:
            try:
                store.migrate()
            except BaseException:
                store.close()
                raise
        return store

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.close()
        return False

    def close(self):
        if self._conn is not None:
            conn, self._conn = self._conn, None
            conn.close()

    @property
    def version(self):
        if self._conn is not None:
            try:
                self._version = self._conn.execute("PRAGMA user_version").fetchone()[0]
            except sqlite3.Error:
                pass
        return self._version

    # ------------------------------------------------------------------ guards

    def _check_open(self):
        if self._conn is None:
            raise ConflictError("the store is closed")

    def _guard(self):
        self._check_open()
        version = self.version
        if version < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % version)

    @contextlib.contextmanager
    def _read(self):
        """A consistent read-only view."""
        self._guard()
        conn = self._conn
        try:
            conn.execute("BEGIN")
            try:
                yield conn
            finally:
                conn.execute("ROLLBACK")
        except sqlite3.Error as exc:
            raise ConflictError("database error: %s" % exc)

    @contextlib.contextmanager
    def _write(self):
        """An all-or-nothing write transaction; waits up to five seconds for other writers."""
        self._guard()
        conn = self._conn
        try:
            conn.execute("BEGIN IMMEDIATE")
        except sqlite3.Error as exc:
            raise ConflictError("database is busy: %s" % exc)
        try:
            yield conn
            conn.execute("COMMIT")
        except BaseException as exc:
            with contextlib.suppress(sqlite3.Error):
                conn.execute("ROLLBACK")
            if isinstance(exc, sqlite3.Error):
                raise ConflictError("database error: %s" % exc)
            raise

    # ------------------------------------------------------------------ migrations

    def migrate(self):
        """Apply the missing schema steps in order; returns the versions applied."""
        self._check_open()
        applied = []
        for step in range(1, LATEST_VERSION + 1):
            if self.version >= step:
                continue
            if self._apply_step(step):
                applied.append(step)
        return applied

    def _apply_step(self, step):
        conn = self._conn
        try:
            conn.execute("BEGIN IMMEDIATE")
        except sqlite3.Error as exc:
            raise _migration_error(step, exc)
        try:
            if conn.execute("PRAGMA user_version").fetchone()[0] >= step:
                conn.execute("ROLLBACK")
                return False
            getattr(self, "_step%d" % step)(conn)
            conn.execute("PRAGMA user_version = %d" % step)
            conn.execute("COMMIT")
        except Exception as exc:
            with contextlib.suppress(sqlite3.Error):
                conn.execute("ROLLBACK")
            raise _migration_error(step, exc)
        self._version = step
        return True

    @staticmethod
    def _step1(conn):
        conn.execute("""CREATE TABLE accounts (path TEXT PRIMARY KEY, type TEXT NOT NULL, currency TEXT, opened TEXT,
                       note TEXT NOT NULL DEFAULT '')""")
        conn.execute("""CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL,
                       payee TEXT NOT NULL, narration TEXT NOT NULL DEFAULT '', cleared INTEGER NOT NULL DEFAULT 1)""")
        conn.execute("""CREATE TABLE postings (id INTEGER PRIMARY KEY AUTOINCREMENT,
                       tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
                       seq INTEGER NOT NULL, account TEXT NOT NULL REFERENCES accounts(path),
                       minor INTEGER NOT NULL, currency TEXT NOT NULL)""")
        conn.execute("CREATE INDEX transactions_date ON transactions (date, id)")
        conn.execute("CREATE INDEX postings_tx ON postings (tx_id, seq)")

    @staticmethod
    def _step2(conn):
        conn.execute("""CREATE TABLE tags (tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
                       tag TEXT NOT NULL, PRIMARY KEY (tx_id, tag))""")
        conn.execute("ALTER TABLE transactions ADD COLUMN flag TEXT NOT NULL DEFAULT '*'")
        conn.execute("ALTER TABLE postings ADD COLUMN note TEXT NOT NULL DEFAULT ''")
        bad = conn.execute("SELECT COUNT(*) FROM transactions WHERE cleared IS NULL OR cleared NOT IN (0, 1)")
        if bad.fetchone()[0]:
            raise ValueError("a transaction has a 'cleared' value that is neither 0 nor 1")
        conn.execute("UPDATE transactions SET flag = CASE cleared WHEN 1 THEN '*' ELSE '!' END")

    @staticmethod
    def _step3(conn):
        conn.execute("""CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL,
                       rate_text TEXT NOT NULL, PRIMARY KEY (src, dst, on_date))""")
        conn.execute("ALTER TABLE accounts ADD COLUMN closed TEXT")

        def clean(value):
            return str(value).strip().upper() if value is not None else ""

        def is_code(text):
            return len(text) == 3 and all("A" <= c <= "Z" for c in text)

        for path, cur in conn.execute("SELECT path, currency FROM accounts").fetchall():
            cleaned = clean(cur)
            if cleaned and not is_code(cleaned):
                raise ValueError("account %s has the currency %r" % (path, cur))
            conn.execute("UPDATE accounts SET currency = ? WHERE path = ?", (cleaned or None, path))
        for pid, cur in conn.execute("SELECT id, currency FROM postings").fetchall():
            cleaned = clean(cur)
            if not is_code(cleaned):
                raise ValueError("posting %s has the currency %r" % (pid, cur))
            conn.execute("UPDATE postings SET currency = ? WHERE id = ?", (cleaned, pid))

    @staticmethod
    def _step4(conn):
        conn.execute("""CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL,
                       currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))""")
        conn.execute("""CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL,
                       start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)""")
        conn.execute("CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)")
        conn.execute("CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
        conn.execute("""CREATE TABLE import_keys (key TEXT PRIMARY KEY,
                       tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)""")

    # ------------------------------------------------------------------ accounts

    @staticmethod
    def _account_from_row(row):
        path, type_, cur, opened, note, closed = row
        return Account(path, type_, cur, _optional_date(opened), _optional_date(closed), note or "")

    def _stored_accounts(self, conn):
        rows = conn.execute("SELECT path, type, currency, opened, note, closed FROM accounts").fetchall()
        accounts = [self._account_from_row(r) for r in rows]
        accounts.sort(key=lambda a: _path_key(a.path))
        return accounts

    def _build_chart(self, conn):
        chart = Chart()
        stored = self._stored_accounts(conn)
        for acc in stored:
            try:
                chart.add(acc.path, type=acc.type, currency=acc.currency, opened=acc.opened, note=acc.note)
            except ChartError as exc:
                raise ConflictError("the book holds an invalid account %s: %s" % (acc.path, exc.message))
            if acc.closed is not None:
                chart.get(acc.path).closed = acc.closed
        return chart, {a.path for a in stored}

    def _build_rates(self, conn):
        table = RateTable()
        for src, dst, on_date, text in conn.execute(
                "SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date"):
            table.set(src, dst, text, _stored_date(on_date))
        return table

    def _filtered_accounts(self, conn, type, under, currency, include_closed):
        if type is not None and type not in _TYPES:
            raise ValidationError("unknown account type %r (expected one of %s)" % (type, ", ".join(_TYPES)))
        if under is not None and not valid_path(under):
            raise ChartError("invalid account path %r" % (under,))
        if currency is not None:
            _currency(currency)
        result = []
        for acc in self._stored_accounts(conn):
            if type is not None and acc.type != type:
                continue
            if under is not None and acc.path != under and not acc.path.startswith(under + ":"):
                continue
            if currency is not None and acc.currency != currency:
                continue
            if not include_closed and acc.closed is not None:
                continue
            result.append(acc)
        return result

    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        with self._write() as conn:
            chart, _ = self._build_chart(conn)
            acc = chart.add(path, type=type, currency=currency, opened=opened, note=note)
            conn.execute("INSERT INTO accounts (path, type, currency, opened, note) VALUES (?, ?, ?, ?, ?)",
                         (acc.path, acc.type, acc.currency, _iso(acc.opened), acc.note))
            return dataclasses.replace(acc)

    def get_account(self, path):
        with self._read() as conn:
            return self._get_account(conn, path)

    def _get_account(self, conn, path):
        row = None
        if isinstance(path, str):
            row = conn.execute("SELECT path, type, currency, opened, note, closed FROM accounts WHERE path = ?",
                               (path,)).fetchone()
        if row is None:
            raise NotFoundError("no such account: %s" % (path,))
        return self._account_from_row(row)

    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._read() as conn:
            return self._filtered_accounts(conn, type, under, currency, include_closed)

    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        return len(self.accounts(type, under, currency, include_closed))

    def chart(self):
        with self._read() as conn:
            return self._build_chart(conn)[0]

    def close_account(self, path, on):
        with self._write() as conn:
            self._get_account(conn, path)
            chart, _ = self._build_chart(conn)
            chart.close(path, on)
            latest = conn.execute(
                "SELECT MAX(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id WHERE p.account = ?",
                (path,)).fetchone()[0]
            if latest is not None and _stored_date(latest) > on:
                raise ConflictError("cannot close %s on %s: it has a posting on %s" % (path, on.isoformat(), latest))
            conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (on.isoformat(), path))
            return dataclasses.replace(chart.get(path))

    def set_account_note(self, path, note):
        _check_text(note, "note")
        with self._write() as conn:
            self._get_account(conn, path)
            conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
            return self._get_account(conn, path)

    def delete_account(self, path):
        with self._write() as conn:
            self._get_account(conn, path)
            if conn.execute("SELECT 1 FROM postings WHERE account = ? LIMIT 1", (path,)).fetchone():
                raise ConflictError("cannot delete %s: transactions have posted to it" % path)
            conn.execute("DELETE FROM accounts WHERE path = ?", (path,))

    # ------------------------------------------------------------------ reading transactions

    def _assemble(self, conn, tx_rows, post_rows, tag_rows):
        postings = {}
        for tx_id, account, minor, cur, note in post_rows:
            postings.setdefault(tx_id, []).append(Posting(account, Money(minor, cur), note or ""))
        tags = {}
        for tx_id, tag in tag_rows:
            tags.setdefault(tx_id, []).append(tag)
        result = []
        for tx_id, date, payee, narration, flag in tx_rows:
            result.append(Transaction(_stored_date(date), payee, narration or "", postings.get(tx_id, []),
                                      tuple(sorted(tags.get(tx_id, []))), flag, tx_id))
        return result

    _TX_COLUMNS = "id, date, payee, narration, flag"
    _POSTING_COLUMNS = "tx_id, account, minor, currency, note"

    def _load_all(self, conn):
        return self._assemble(
            conn,
            conn.execute("SELECT %s FROM transactions ORDER BY date, id" % self._TX_COLUMNS).fetchall(),
            conn.execute("SELECT %s FROM postings ORDER BY tx_id, seq, id" % self._POSTING_COLUMNS).fetchall(),
            conn.execute("SELECT tx_id, tag FROM tags").fetchall())

    def _load_page(self, conn, limit, offset):
        limit = -1 if limit is None else limit
        sub = "SELECT id FROM transactions ORDER BY date, id LIMIT ? OFFSET ?"
        return self._assemble(
            conn,
            conn.execute("SELECT %s FROM transactions ORDER BY date, id LIMIT ? OFFSET ?" % self._TX_COLUMNS,
                         (limit, offset)).fetchall(),
            conn.execute("SELECT %s FROM postings WHERE tx_id IN (%s) ORDER BY tx_id, seq, id"
                         % (self._POSTING_COLUMNS, sub), (limit, offset)).fetchall(),
            conn.execute("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s)" % sub, (limit, offset)).fetchall())

    def _load_ids(self, conn, ids):
        result = []
        ids = list(ids)
        for start in range(0, len(ids), 500):
            chunk = ids[start:start + 500]
            marks = ",".join("?" * len(chunk))
            result.extend(self._assemble(
                conn,
                conn.execute("SELECT %s FROM transactions WHERE id IN (%s)" % (self._TX_COLUMNS, marks),
                             chunk).fetchall(),
                conn.execute("SELECT %s FROM postings WHERE tx_id IN (%s) ORDER BY tx_id, seq, id"
                             % (self._POSTING_COLUMNS, marks), chunk).fetchall(),
                conn.execute("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s)" % marks, chunk).fetchall()))
        result.sort(key=lambda t: (t.date, t.id))
        return result

    def _query_object(self, conn, query):
        if query is None:
            return None
        if isinstance(query, Query):
            return None if query.is_empty else query
        if isinstance(query, str):
            if not query.strip():
                return None
            return parse_query(query, self._build_chart(conn)[0])
        raise ValidationError("query must be text or a parsed Query, not %r" % (query,))

    def transactions(self, query=None, limit=None, offset=0):
        limit = _check_limit(limit, "limit", True)
        offset = _check_limit(offset, "offset", False)
        with self._read() as conn:
            parsed = self._query_object(conn, query)
            if parsed is None:
                return self._load_page(conn, limit, offset)
            matching = [t for t in self._load_all(conn) if parsed.matches(t)]
        matching = matching[offset:]
        return matching if limit is None else matching[:limit]

    def count_transactions(self, query=None):
        with self._read() as conn:
            parsed = self._query_object(conn, query)
            if parsed is None:
                return conn.execute("SELECT COUNT(*) FROM transactions").fetchone()[0]
            return sum(1 for t in self._load_all(conn) if parsed.matches(t))

    def has_import_key(self, key):
        with self._read() as conn:
            return conn.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone() is not None

    def get_transaction(self, id):
        with self._read() as conn:
            return self._get_transaction(conn, id)

    def _get_transaction(self, conn, id):
        found = self._load_ids(conn, [id]) if _is_int(id) and 0 < id <= _MAX_INT else []
        if not found:
            raise NotFoundError("no transaction %s" % (id,))
        return found[0]

    def ledger(self):
        with self._read() as conn:
            chart, _ = self._build_chart(conn)
            ledger = Ledger(chart, self._build_rates(conn))
            ledger.add_many(self._load_all(conn))
            return ledger

    # ------------------------------------------------------------------ writing transactions

    def _insert_transaction(self, conn, tx, key=None):
        flag = tx.flag
        cur = conn.execute("INSERT INTO transactions (date, payee, narration, cleared, flag) VALUES (?, ?, ?, ?, ?)",
                           (tx.date.isoformat(), tx.payee, tx.narration, 1 if flag == "*" else 0, flag))
        tx_id = cur.lastrowid
        for seq, p in enumerate(tx.postings):
            conn.execute("INSERT INTO postings (tx_id, seq, account, minor, currency, note) VALUES (?, ?, ?, ?, ?, ?)",
                         (tx_id, seq, p.account, p.amount.minor, p.amount.currency, p.note))
        for tag in tx.tags:
            conn.execute("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", (tx_id, tag))
        if key is not None:
            conn.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (key, tx_id))
        return tx_id

    def _store_validated(self, conn, ledger, stored_paths, tx, key=None):
        """Validate ``tx`` with ``ledger`` and write it; returns the stored transaction."""
        if not isinstance(tx, Transaction):
            raise LedgerError("expected a Transaction, not %r" % (tx,))
        checked = ledger.add(dataclasses.replace(tx, id=None))
        for p in checked.postings:
            if p.account not in stored_paths:
                raise LedgerError("unknown account %s: only accounts that were added can be posted to" % p.account)
        tx_id = self._insert_transaction(conn, checked, key)
        return dataclasses.replace(checked, id=tx_id)

    def _new_ledger(self, conn):
        chart, stored = self._build_chart(conn)
        return Ledger(chart, self._build_rates(conn)), stored

    def add_transaction(self, tx):
        with self._write() as conn:
            ledger, stored = self._new_ledger(conn)
            return self._store_validated(conn, ledger, stored, tx)

    def add_transactions(self, txs, keys=None):
        txs = list(txs)
        if keys is not None:
            keys = list(keys)
            if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
                raise ValidationError("keys must be one text per transaction")
        result = BulkAdd()
        with self._write() as conn:
            ledger, stored = self._new_ledger(conn)
            seen = set()
            for index, tx in enumerate(txs):
                key = None if keys is None else keys[index]
                if key is not None and (key in seen or conn.execute(
                        "SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone()):
                    result.skipped.append(index)
                    continue
                try:
                    result.added.append(self._store_validated(conn, ledger, stored, tx, key))
                except TallybookError as exc:
                    exc.detail = {"index": index}
                    raise
                if key is not None:
                    seen.add(key)
        return result

    def delete_transaction(self, id):
        with self._write() as conn:
            tx = self._get_transaction(conn, id)
            for table, column in (("import_keys", "tx_id"), ("tags", "tx_id"), ("postings", "tx_id"),
                                  ("transactions", "id")):
                conn.execute("DELETE FROM %s WHERE %s = ?" % (table, column), (id,))
            return tx

    # ------------------------------------------------------------------ rates

    def set_rate(self, src, dst, rate_text, on):
        RateTable().set(src, dst, rate_text, on)
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                         (src, dst, on.isoformat(), rate_text))

    def remove_rate(self, src, dst, on):
        _currency(src)
        _currency(dst)
        if not _is_date(on):
            raise CurrencyError("rate date must be a date, not %r" % (on,))
        with self._write() as conn:
            cur = conn.execute("DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?",
                               (src, dst, on.isoformat()))
            if cur.rowcount == 0:
                raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, on.isoformat()))

    def rate_rows(self):
        with self._read() as conn:
            rows = conn.execute("SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")
            return [(s, d, _stored_date(o), t) for s, d, o, t in rows]

    def rate_table(self):
        with self._read() as conn:
            return self._build_rates(conn)

    # ------------------------------------------------------------------ budgets

    def add_budget(self, budget):
        if not isinstance(budget, Budget):
            raise ValidationError("expected a Budget, not %r" % (budget,))
        with self._write() as conn:
            if conn.execute("SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
                            (budget.pattern, budget.period_kind)).fetchone():
                raise ConflictError("a budget for %s per %s already exists" % (budget.pattern, budget.period_kind))
            conn.execute("INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) VALUES (?, ?, ?, ?, ?)",
                         (budget.pattern, budget.period_kind, budget.amount.minor, budget.amount.currency,
                          budget.start.isoformat()))

    def remove_budget(self, pattern, period_kind):
        with self._write() as conn:
            cur = conn.execute("DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind))
            if cur.rowcount == 0:
                raise NotFoundError("no budget for %s per %s" % (pattern, period_kind))

    def budgets(self):
        with self._read() as conn:
            rows = conn.execute("SELECT pattern, period_kind, minor, currency, start_date FROM budgets "
                                "ORDER BY pattern, period_kind").fetchall()
            return [Budget(p, k, Money(m, c), _stored_date(s)) for p, k, m, c, s in rows]

    # ------------------------------------------------------------------ recurring

    @staticmethod
    def _template_to_json(tx):
        def money(m):
            return None if m is None else {"amount": m.amount_str(), "currency": m.currency}
        return json.dumps({
            "date": _iso(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration, "flag": tx.flag,
            "tags": list(tx.tags),
            "postings": [{"account": p.account, "amount": money(p.amount), "note": p.note} for p in tx.postings],
        }, sort_keys=True)

    @staticmethod
    def _template_from_json(text):
        data = json.loads(text)
        postings = [Posting(p["account"], None if p["amount"] is None
                            else Money.of(p["amount"]["amount"], p["amount"]["currency"]), p["note"])
                    for p in data["postings"]]
        return Transaction(_optional_date(data["date"]), data["payee"], data["narration"], postings,
                           tuple(data["tags"]), data["flag"], data["id"])

    def _recurring_rows(self, conn):
        rows = conn.execute("SELECT name, schedule, template, start_date, end_date, max_count, "
                            "materialized_through FROM recurring ORDER BY name").fetchall()
        return [(Recurring(n, s, self._template_from_json(t), _stored_date(st), _optional_date(e), c),
                 _optional_date(m)) for n, s, t, st, e, c, m in rows]

    def add_recurring(self, rec):
        if not isinstance(rec, Recurring):
            raise ValidationError("expected a Recurring, not %r" % (rec,))
        with self._write() as conn:
            if conn.execute("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)).fetchone():
                raise ConflictError("recurring item %s already exists" % rec.name)
            conn.execute("INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count) "
                         "VALUES (?, ?, ?, ?, ?, ?)",
                         (rec.name, str(rec.schedule), self._template_to_json(rec.template),
                          rec.start.isoformat(), _iso(rec.end), rec.count))

    def remove_recurring(self, name):
        with self._write() as conn:
            if conn.execute("DELETE FROM recurring WHERE name = ?", (name,)).rowcount == 0:
                raise NotFoundError("no recurring item %s" % (name,))

    def recurring(self):
        with self._read() as conn:
            return [rec for rec, _ in self._recurring_rows(conn)]

    def materialized_through(self, name):
        with self._read() as conn:
            row = conn.execute("SELECT materialized_through FROM recurring WHERE name = ?", (name,)).fetchone()
            if row is None:
                raise NotFoundError("no recurring item %s" % (name,))
            return _optional_date(row[0])

    def materialize(self, upto=None, today=None):
        horizons = []
        for what, value in (("upto", upto), ("today", today)):
            if value is not None:
                if not _is_date(value):
                    raise ValidationError("%s must be a date, not %r" % (what, value))
                horizons.append(value)
        if not horizons:
            raise ValidationError("materialize needs a horizon: give upto or today")
        horizon = min(horizons)
        with self._write() as conn:
            series = self._recurring_rows(conn)
            due = []
            for rec, through in series:
                low = rec.start
                if through is not None and through < datetime.date.max:
                    low = max(low, through + datetime.timedelta(days=1))
                if through is not None and through == datetime.date.max:
                    continue
                if low <= horizon:
                    due.extend((d, rec.name, rec) for d in occurrences(rec, low, horizon))
            due.sort(key=lambda item: (item[0], item[1]))
            ledger, stored = self._new_ledger(conn)
            made = [self._store_validated(conn, ledger, stored, instantiate(rec, d)) for d, _, rec in due]
            for rec, through in series:
                if through is None or horizon > through:
                    conn.execute("UPDATE recurring SET materialized_through = ? WHERE name = ?",
                                 (horizon.isoformat(), rec.name))
            return made

    # ------------------------------------------------------------------ rules, settings, profiles

    def set_rules(self, text):
        _check_text(text, "rules")
        parse_rules(text)
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO rules (id, body) VALUES (1, ?)", (text,))

    def rules_text(self):
        with self._read() as conn:
            row = conn.execute("SELECT body FROM rules WHERE id = 1").fetchone()
            return "" if row is None else row[0]

    def rules(self):
        return parse_rules(self.rules_text())

    def get_setting(self, key, default=None):
        with self._read() as conn:
            row = conn.execute("SELECT value FROM settings WHERE key = ?", (key,)).fetchone() \
                if isinstance(key, str) else None
            return default if row is None else row[0]

    def set_setting(self, key, value):
        if not isinstance(key, str) or not key:
            raise ValidationError("a setting key must be non-empty text, not %r" % (key,))
        _check_text(value, "a setting value")
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (key, value))

    def delete_setting(self, key):
        with self._write() as conn:
            conn.execute("DELETE FROM settings WHERE key = ?", (key,))

    def settings(self):
        with self._read() as conn:
            return dict(conn.execute("SELECT key, value FROM settings ORDER BY key").fetchall())

    def set_profile(self, name, text):
        if not isinstance(name, str) or not _PROFILE_NAME.fullmatch(name):
            raise ValidationError("invalid profile name %r (letters, digits, _ and -, starting with a letter or digit)"
                                  % (name,))
        _check_text(text, "profile text")
        parse_profile(text)
        self.set_setting("profile." + name, text)

    def profile_text(self, name):
        text = self.get_setting("profile." + name) if isinstance(name, str) else None
        if text is None:
            raise NotFoundError("no such profile: %s" % (name,))
        return text

    def profiles(self):
        return sorted(k[len("profile."):] for k in self.settings() if k.startswith("profile."))

    def remove_profile(self, name):
        self.profile_text(name)
        self.delete_setting("profile." + name)

    # ------------------------------------------------------------------ CSV import and journals

    @staticmethod
    def _import_key_base(tx, account):
        first = next(p for p in tx.postings if p.account == account)
        return "%s|%s|%s|%d %s" % (tx.date.isoformat(), tx.payee, account, first.amount.minor,
                                   first.amount.currency)

    def import_csv(self, text, profile, apply_rules=True):
        if isinstance(profile, str) and _NAME_CHARS.fullmatch(profile):
            profile = self.profile_text(profile)
        if isinstance(profile, str):
            profile = parse_profile(profile)
        if not isinstance(profile, ImportProfile):
            raise ValidationError("profile must be a name, profile text or an ImportProfile")
        rules = self.rules() if apply_rules else None
        with self._write() as conn:
            ids = [r[0] for r in conn.execute("SELECT DISTINCT tx_id FROM postings WHERE account = ?",
                                              (profile.account,))]
            existing = self._load_ids(conn, ids)
            result = _import_csv(text, profile, rules, existing)
            outcome = ImportOutcome([], list(result.duplicates), list(result.errors))
            if result.errors:
                return outcome
            seen_before = {}
            for dup in result.duplicates:
                base = self._import_key_base(dup, profile.account)
                seen_before[base] = seen_before.get(base, 0) + 1
            ledger, stored = self._new_ledger(conn)
            for index, tx in enumerate(result.transactions):
                base = self._import_key_base(tx, profile.account)
                n = seen_before.get(base, 0) + 1
                while conn.execute("SELECT 1 FROM import_keys WHERE key = ?", ("%s|%d" % (base, n),)).fetchone():
                    n += 1
                seen_before[base] = n
                try:
                    outcome.added.append(self._store_validated(conn, ledger, stored, tx, "%s|%d" % (base, n)))
                except TallybookError as exc:
                    exc.detail = {"index": index}
                    raise
            return outcome

    def journal(self):
        with self._read() as conn:
            return Journal(accounts=self._stored_accounts(conn),
                           rates=[(s, d, _stored_date(o), t) for s, d, o, t in conn.execute(
                               "SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")],
                           transactions=[dataclasses.replace(t, id=None) for t in self._load_all(conn)])

    def load_journal(self, journal):
        with self._write() as conn:
            chart, stored = self._build_chart(conn)
            rates = self._build_rates(conn)
            for acc in journal.accounts:
                added = chart.add(acc.path, type=acc.type, currency=acc.currency, opened=acc.opened, note=acc.note)
                if acc.closed is not None:
                    chart.close(acc.path, acc.closed)
                conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                             "VALUES (?, ?, ?, ?, ?, ?)",
                             (added.path, added.type, added.currency, _iso(added.opened), added.note,
                              _iso(added.closed)))
                stored.add(added.path)
            for src, dst, on, text in journal.rates:
                rates.set(src, dst, text, on)
                conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                             (src, dst, on.isoformat(), text))
            ledger = Ledger(chart, rates)
            return [self._store_validated(conn, ledger, stored, tx) for tx in journal.transactions]

    # ------------------------------------------------------------------ health, backup, status

    def check(self):
        problems = []
        with self._read() as conn:
            try:
                for (line,) in conn.execute("PRAGMA integrity_check").fetchall():
                    if line != "ok":
                        problems.append("integrity check failed: %s" % line)
            except sqlite3.Error as exc:
                problems.append("integrity check failed: %s" % exc)
            for pid, tx_id in conn.execute("SELECT id, tx_id FROM postings WHERE tx_id NOT IN "
                                           "(SELECT id FROM transactions)"):
                problems.append("posting %d belongs to missing transaction %d" % (pid, tx_id))
            for tx_id, tag in conn.execute("SELECT tx_id, tag FROM tags WHERE tx_id NOT IN "
                                           "(SELECT id FROM transactions)"):
                problems.append("tag %s belongs to missing transaction %d" % (tag, tx_id))
            for key, tx_id in conn.execute("SELECT key, tx_id FROM import_keys WHERE tx_id NOT IN "
                                           "(SELECT id FROM transactions)"):
                problems.append("import key %s belongs to missing transaction %d" % (key, tx_id))
            for (tx_id,) in conn.execute("SELECT id FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)"):
                problems.append("transaction %d has no postings" % tx_id)
            for pid, tx_id, account in conn.execute(
                    "SELECT id, tx_id, account FROM postings WHERE account NOT IN (SELECT path FROM accounts)"):
                problems.append("posting %d of transaction %d is on unknown account %s" % (pid, tx_id, account))
            for tx_id, cur, total in conn.execute(
                    "SELECT p.tx_id, p.currency, SUM(p.minor) FROM postings p JOIN transactions t ON t.id = p.tx_id "
                    "GROUP BY p.tx_id, p.currency HAVING SUM(p.minor) != 0"):
                try:
                    shown = format_minor(total, cur)
                except TallybookError:
                    shown = str(total)
                problems.append("transaction %d does not balance: %s %s" % (tx_id, cur, shown))
        return sorted(problems)

    def backup(self, dest):
        self._guard()
        if isinstance(dest, bytes):
            dest = os.fsdecode(dest)
        dest = os.fspath(dest)
        try:
            os.close(os.open(dest, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644))
        except FileExistsError:
            raise ConflictError("%s already exists" % dest)
        except (FileNotFoundError, NotADirectoryError):
            raise NotFoundError("no such directory for %s" % dest)
        except OSError as exc:
            raise ConflictError("cannot create %s: %s" % (dest, exc))
        target = sqlite3.connect(dest)
        try:
            self._conn.backup(target)
        except sqlite3.Error as exc:
            target.close()
            with contextlib.suppress(OSError):
                os.unlink(dest)
            raise ConflictError("backup failed: %s" % exc)
        target.close()

    def info(self):
        with self._read() as conn:
            counts = {name: conn.execute("SELECT COUNT(*) FROM %s" % name).fetchone()[0]
                      for name in ("accounts", "transactions", "postings", "rates", "budgets", "recurring")}
        info = {"path": self.path, "version": self.version}
        info.update(counts)
        return info

